from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Preformatted, PageBreak, Table, TableStyle
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import letter
from xml.sax.saxutils import escape
from pathlib import Path

out=Path('output/pdf/capstone_code_beginner_guide.pdf')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='GuideTitle',fontName='Helvetica-Bold',fontSize=23,leading=28,spaceAfter=16))
styles.add(ParagraphStyle(name='SectionTitle',fontName='Helvetica-Bold',fontSize=17,leading=21,spaceAfter=13))
styles.add(ParagraphStyle(name='FileTitle',fontName='Helvetica-Bold',fontSize=11.5,leading=15,spaceBefore=10,spaceAfter=5,keepWithNext=True))
styles.add(ParagraphStyle(name='Text',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=8))
styles.add(ParagraphStyle(name='CodeText',fontName='Courier',fontSize=8.5,leading=12,spaceAfter=10))
story=[]
def p(t): story.append(Paragraph(t,styles['Text']))
def h(t): story.append(Paragraph(t,styles['FileTitle']))
def title(t): story.append(Paragraph(t,styles['SectionTitle']))
def code(t): story.append(Preformatted(t,styles['CodeText']))
def page(): story.append(PageBreak())
def table(rows,widths):
    data=[[Paragraph(escape(c),styles['Text']) for c in row] for row in rows]
    t=Table(data,colWidths=widths,hAlign='LEFT')
    t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eeeeee')),('LINEBELOW',(0,0),(-1,0),.6,colors.grey),('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5)]))
    story.append(t)

story.append(Paragraph('Your economic data project',styles['GuideTitle']))
p('<b>A beginner\'s guide to the code, files and data pipeline</b><br/>Capstone project | October 25, 2026')
p('This project is a small automated research assistant for economic data. It downloads numbers from public sources, organizes them, calculates economic variables, and produces spreadsheets plus reports about data quality.')
p('The main dataset covers 12 emerging-market countries from January 2000 through December 2019. An optional extension adds U.S. economic observations for the same months.')
h('The overall journey')
code('Public data APIs\n       |\n       v\ndata/raw/         Saved responses and request details\n       |\n       v\ndata/normalized/  Standardized individual series\n       |\n       v\ndata/processed/   Final research tables\n       +\nreports/          Coverage, missing values and source notes')
p('A <b>pipeline</b> is simply a sequence of steps that turns source data into useful output. Keeping each stage separate makes it easier to inspect the data and repeat the work.')
h('What the final table looks like')
p('A <b>panel</b> contains repeated observations for multiple subjects. Here, each row represents one country in one month. Columns contain that month\'s exchange rate, CPI, production, credit and calculated variables.')
code('country    date       nominal_fx    domestic_cpi    ...\nBrazil     2000-01    ...           ...\nBrazil     2000-02    ...           ...\nMexico     2000-01    ...           ...')
p('The main panel has 12 countries x 240 months = <b>2,880 rows</b>. Rows remain in the table even when some values are missing. A full set of rows does not mean all observations are available or all definitions have been validated.')
h('Suggested reading route')
p('Start with download.py, then providers.py, then data_finder.py, then audit.py. Together, these show the central journey from requesting data to calculating the final variables.')
page()
title('1. The folder structure')
code('code/\n  README.md                 Project instructions and research notes\n  requirements.txt          Required Python libraries\n  requirements-tested.txt   Exact versions previously tested\n  setup_fred.py             Configure the FRED API key\n  discover.py               Explore emerging-market sources\n  download.py               Download and standardize selected data\n  data_finder.py            Build the emerging-market panel\n  discover_us.py            Explore U.S. sources\n  us_data_finder.py          Start the U.S. build\n\n  eme_pipeline/             Reusable Python tools\n    __init__.py\n    config.py\n    settings.py\n    http.py\n    providers.py\n    audit.py\n    reporting.py\n    fred.py\n    us.py\n\n  data/\n    raw/                    Saved provider responses\n    normalized/             Individual standardized CSV tables\n    processed/              Final assembled datasets\n\n  reports/                  Quality checks and research explanations\n  tests/                    Automated checks of code behavior')
h('Scripts versus reusable tools')
p('The Python files at the top level are mostly <b>scripts you run</b>. They coordinate a workflow. Files inside eme_pipeline/ provide <b>reusable tools</b> those scripts call. This avoids rewriting the same download or calculation logic in several places.')
h('Supporting and automatically generated files')
p('<b>README.md</b> is the project manual. <b>requirements.txt</b> lists pandas, NumPy, requests and pytest. <b>requirements-tested.txt</b> records exact dependency versions used in a checked environment.')
p('<b>.env</b> stores your local FRED key; <b>.env.example</b> shows the expected setting. <b>.gitignore</b> tells Git which files to exclude, including .env. <b>.git/</b> holds version-control history.')
p('<b>.venv/</b> is the project\'s isolated Python environment. <b>.pytest_cache/</b> and <b>__pycache__/</b> contain automatically generated helper files. <b>.DS_Store</b> is a macOS folder-settings file.')
page()
title('2. A little Python vocabulary')
table([['Term','Meaning in this project'],['Variable','A name holding a value, such as a country code or a table.'],['Function','A named, reusable task, such as downloading one series.'],['Class','A blueprint for an object that groups related tools and settings.'],['DataFrame','A pandas table with rows and columns, similar to a worksheet.'],['Series','A pandas object resembling one column of values.'],['API','A service your code asks for data over the internet.'],['CSV','A plain-text table that Excel can open.'],['JSON','A structured format used for API responses and saved details.'],['Metadata','Information describing data: source, units, frequency and dates.'],['Cache','Saved information reused instead of downloading it again.']],[100,404])
h('Loading libraries and project tools')
code('import pandas as pd\nfrom eme_pipeline.http import Client')
p('The first line loads the pandas library and gives it the short name pd. The second loads the Client tool from your own project\'s eme_pipeline/http.py file.')
h('Defining and starting a function')
code("def main():\n    # Instructions go here\n    ...\n\nif __name__ == '__main__':\n    main()")
p('def defines a function; it does not immediately run its instructions. The final two lines mean: "If someone runs this file directly, start its main() function." Indentation groups instructions together.')
h('Loops, dictionaries and error handling')
p('A <b>for loop</b> repeats a task, such as downloading a series for each country. A <b>dictionary</b> associates keys with values, such as BRA with Brazil. A <b>try/except</b> block attempts work and handles a failure so the program can record it or continue.')
page()
title('3. The scripts you run')
h('setup_fred.py - configure access to FRED')
p('FRED provides U.S. economic data. Its official API needs an access credential called an API key. This script prompts for the key without displaying it, validates its format, and saves it in .env. The --status option checks whether a key is configured. It does not test whether FRED accepts the key.')
h('discover.py - investigate emerging-market sources')
p('Think of this as looking through a library catalog before choosing books. It requests catalogs, descriptions and sample series from sources such as the World Bank, IMF and BCRP. Options explore different candidates. Responses are saved for inspection; some investigated sources never become final panel inputs.')
h('download.py - collect selected data')
p('This loops through countries and requests exchange rates, CPI, industrial production, private credit and available selected sovereign spreads. Provider adapters convert responses to standard tables, which are written under data/normalized/.')
p('If one series fails, unrelated downloads continue. Failures are recorded in reports/download_status.json. An older normalized file for a failed series is renamed with .stale.csv so the builder will not quietly reuse it. The script ends with a failure exit status if any download or parsing job failed.')
h('data_finder.py - assemble and audit the EME panel')
p('This reads normalized CSVs, aligns their dates, calculates research variables, identifies missing observations, and measures how many months contain all four required variables. It writes data/processed/eme_monthly_panel.csv plus quality reports. Despite its name, its main role is building and auditing the panel.')
p('The default EME build works locally without internet access. Adding --include-us also runs the optional U.S. extension; --us-offline makes that extension use saved responses.')
h('discover_us.py - inspect U.S. sources')
p('This retrieves FRED descriptions, including frequency, units, seasonal adjustment and available dates. It also investigates IMF U.S. credit candidates and saves discovery results. It helps determine which series are suitable before building the U.S. table.')
h('us_data_finder.py - launch the U.S. build')
p('This short script reads the --offline option, creates a Client, and calls build() in eme_pipeline/us.py. The original EME panel must exist first because the extension also creates a combined EME-U.S. panel.')
code('build(Client(offline=args.offline))')
p('Read this as: "Build the U.S. dataset using this configured download and cache tool."')
page()
title('4. Reusable tools: settings and retrieval')
h('eme_pipeline/__init__.py - identify the package')
p('This contains a brief description and marks the folder as a Python package. A package lets other files import its tools using names such as eme_pipeline.http. It performs no data processing itself.')
h('eme_pipeline/config.py - shared project choices')
p('This defines the 12 country codes and names, the expected raw input variables, and the four required variables used for complete-case checks. Keeping these choices together helps the scripts use consistent definitions.')
code("COUNTRIES = {'BRA': 'Brazil', 'MEX': 'Mexico', ...}")
h('eme_pipeline/settings.py - read and save credentials')
p('get_fred_api_key() looks for the FRED key in the running process\'s environment first, then in the project .env file. An environment variable is a setting supplied to a program from outside its source code. save_fred_api_key() validates and safely saves a supplied key.')
h('eme_pipeline/http.py - internet requests and caching')
p('This defines Client, the shared tool for requesting and saving responses. Its get() method builds an identity for a request, checks for a successful cached response, verifies its hash, and returns it if available. A hash is a digital fingerprint used to detect changes to saved bytes.')
p('If no successful response is saved, offline mode raises an error. Online mode makes the actual network request with requests.Session.get(). The client adds time limits, retries for certain temporary failures, a short pause before network requests, and credential redaction. It saves a response body and a JSON request manifest. Its json() method also converts returned JSON into Python objects.')
p('<b>Important:</b> successful cached responses are reused even in a normal online run. Rerunning does not automatically download a newer data vintage.')
h('eme_pipeline/providers.py - translate provider formats')
p('Each provider uses different response formats. These adapters translate them into monthly tables with fields such as date, value, frequency and status, retaining extra attributes where available.')
p('<b>wb_pages()</b> handles World Bank pagination. <b>gem()</b> retrieves GEM exchange rates, CPI and production. <b>imf_credit()</b> retrieves and checks IMF credit; <b>imf_cpi()</b> handles IMF CPI. <b>bcrp()</b> retrieves native monthly spreads for comparison. <b>bcrp_daily_monthly()</b> averages daily spreads by month, requiring at least 15 observed days.')
p('For example, a provider date labeled 2000M01 is standardized to 2000-01. The adapters also reject unexpected frequencies or identifying metadata instead of silently accepting a different series.')
page()
title('5. Reusable tools: calculations and U.S. data')
h('eme_pipeline/audit.py - validate and calculate')
p('<b>clean()</b> checks monthly dates, rejects duplicate months, converts values to numbers and sorts the series. <b>coverage()</b> measures which target months contain usable observations. <b>complete_cases()</b> finds rows with every required variable.')
p('<b>transform()</b> calculates the main EME variables:')
code('real_fx = nominal_fx * us_cpi / domestic_cpi\nlog_real_fx = ln(real_fx)\nlog_ip = ln(industrial_production)\nreal_credit = nominal_credit / (domestic_cpi / 100)\nannual_growth = 100 * (real_credit[t] / real_credit[t-12] - 1)')
p('The code aligns observations to a complete monthly calendar before taking lags. Going back 12 rows then truly means 12 months. It retains 1999 internally so January 2000 can have annual growth. Nonpositive inputs to logs and certain derived variables are treated as missing.')
p('usd_spread_bp() is a helper for calculating yield differences under specified conditions. The selected panel spreads come from BCRP EMBIG series.')
h('eme_pipeline/reporting.py - explain results and alternatives')
p('This produces candidate audits, source comparisons and written research findings. For example, it compares monthly averages calculated from daily spreads with native monthly spreads. It uses an offline client: API-looking calls here read saved responses rather than making network requests. Investigated candidates are distinguished from selected panel inputs.')
h('eme_pipeline/fred.py - communicate with FRED')
p('The Fred class uses the shared Client. query() attaches credentials and requests an endpoint; metadata() retrieves a series description; monthly() retrieves observations and handles pagination. It checks monthly frequency and dates, rejects duplicate months, and converts FRED\'s "." missing-value marker into a missing numeric value. Live access requires a key; offline replay does not.')
h('eme_pipeline/us.py - build and attach U.S. data')
p('build() coordinates retrieval, validation, calculations, merging and output. Inputs include FEDFUNDS (interest rate), PCE and PCEC96 (consumption), INDPRO (production), CPIAUCSL (prices), and LOANS plus other credit candidates. validate_metadata() checks units, frequency and adjustment; transform_us() calculates variables; write_us_report() explains results.')
p('The builder tries IMF credit first. If usable IMF observations are unavailable, it selects FRED LOANS as an explicitly labeled proxy. Main U.S. annual credit growth is 100 times a 12-month log difference; an arithmetic version is also provided for comparison with EME growth.')
p('merge_us() joins by month, repeats U.S. values across countries, and checks that rows and original columns are preserved. FRED CPI becomes us_credit_cpi in the combined table, preserving the existing GEM us_cpi.')
page()
title('6. Data outputs, reports and tests')
h('The three data stages')
p('<b>data/raw/</b> holds response bodies (.body) and request manifests (.json), organized by provider and country. These preserve evidence of what was retrieved and allow replay. Credential values are redacted.')
p('<b>data/normalized/</b> holds standardized individual series. For example, data/normalized/BRA/nominal_fx.csv is Brazil\'s exchange-rate table. Separating these tables from the final panel makes parsing and calculations easier to inspect.')
p('<b>data/processed/</b> holds three final research tables:')
code('eme_monthly_panel.csv       Emerging-market observations\nus_monthly_macro.csv        One U.S. row per month\neme_us_monthly_panel.csv     EME observations with U.S. columns')
h('The most useful reports')
table([['Report','What it tells you'],['research_findings.md','Written explanation of EME results and limitations.'],['series_coverage.csv','How many usable observations each series has.'],['missing_months.csv','Exactly which observations are missing.'],['source_registry.csv','Sources, series definitions and caveats.'],['country_eligibility.csv','Months with all required variables; research clearance is separate.'],['download_status.json','Which download jobs succeeded or failed.'],['credit_lag_coverage.csv','Availability of current and year-earlier inputs.'],['observation_flags.csv','Large adjacent changes needing review.']],[160,344])
p('Many reports have corresponding us_ versions. U.S. integration integrity records hashes and row counts to check that the original EME file is preserved. Log files record output from earlier runs.')
h('Automated tests')
p('<b>tests/test_audit.py</b> checks calendars, missing values, calculations and complete cases. <b>tests/test_providers.py</b> checks parsing, pagination and daily aggregation. <b>tests/test_settings.py</b> checks credential handling. <b>tests/test_us.py</b> checks U.S. calculations, FRED handling, merging, caching and redaction.')
p('A test supplies known inputs and checks the expected answer. For example, real credit rising from 100 to 110 over a year should produce 10% arithmetic growth. These files check code behavior; economic comparability still requires source review.')
page()
title('7. Follow one observation from start to finish')
p('Suppose you want Brazil\'s real-credit growth for January 2000. The following sequence connects the files you have just read about.')
h('Step 1 - request the inputs')
p('download.py asks providers.py for Brazil\'s nominal private credit and CPI. The adapters construct the relevant IMF and World Bank requests.')
h('Step 2 - retrieve or replay the response')
p('providers.py uses http.py. The Client returns verified cached data if available; otherwise it makes a network request when online. It saves the response and request details under data/raw/.')
h('Step 3 - standardize the observations')
p('The adapters parse provider-specific formats into monthly tables. download.py saves those tables under data/normalized/BRA/.')
h('Step 4 - align the dates and calculate')
p('data_finder.py reads the tables. audit.py aligns them to the monthly calendar, calculates real credit for January 1999 and January 2000, and calculates the percentage change between them.')
code('Illustrative values only:\n\nJanuary 1999 real credit = 100\nJanuary 2000 real credit = 110\n\nGrowth = 100 * (110 / 100 - 1) = 10%')
h('Step 5 - save the result and its audit trail')
p('The result becomes a value in data/processed/eme_monthly_panel.csv. Coverage and lag reports record whether the required inputs existed. If either month\'s credit or CPI is missing or invalid, growth stays missing.')
h('Commands that connect the stages')
code('# Rebuild EME data from saved responses\n.venv/bin/python download.py --offline\n.venv/bin/python data_finder.py\n\n# Add the U.S. extension from saved responses\n.venv/bin/python us_data_finder.py --offline\n\n# Run the automated checks\n.venv/bin/python -m pytest -q')
p('Offline commands require matching saved responses. To make live requests, omit --offline; official FRED access also needs the configured key. Successful cached responses are still reused.')
p('<b>Research boundary:</b> this project collects and audits data. It does not fill missing observations, estimate a VAR, identify policy shocks, or certify that every source definition is fully comparable.')

def footer(c,doc):
    c.setStrokeColor(colors.HexColor('#bbbbbb')); c.line(54,44,558,44)
    c.setFont('Helvetica',8); c.setFillColor(colors.HexColor('#555555'))
    c.drawString(54,31,'Capstone code | Beginner guide'); c.drawRightString(558,31,f'{doc.page}')
SimpleDocTemplate(str(out),pagesize=letter,rightMargin=54,leftMargin=54,topMargin=48,bottomMargin=57,title='Capstone code: a beginner guide',author='').build(story,onFirstPage=footer,onLaterPages=footer)
print(out.resolve())
